sourceText:
struct A<T>
{
    static A<A<T>> x;
}

struct B<T>
{
    static A<B<T>> x;
}

struct C<T>
{
    static D<T> x;
}
struct D<T>
{
    static C<D<T>> x;
}
#pragma warning disable CS0067 // The event 'E<T>.x' is never used
struct E<T>
{
    static event E<E<T>> x;
}

